package com.oms.supplychain.service.wms;

import com.oms.supplychain.service.warehouse.impl.PurchaseWorkspaceService;
import org.springframework.stereotype.Service;
import org.springframework.context.annotation.Lazy;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Receipt-scoped cancellation intent. All transitions lock purchase -> receipt -> ticket -> WMS task. */
@Service
public class PurchaseCutoffService {
    @Resource private WmsStore db;
    @Resource private PurchaseWorkspaceService purchase;
    @Resource @Lazy private WmsInboundService inbound;
    private static class Review extends IllegalArgumentException { Review(String message){super(message);} }
    private boolean active(Map<String,Object> row){return !text(row.get("cutoffState")).isEmpty()&&!"COMPLETED".equals(row.get("cutoffState"));}
    private long received(String company,String sn){return db.jdbc.queryForObject("SELECT COALESCE(SUM(number_actually),0) FROM wms_tickets_goods WHERE UPPER(company_code)=? AND sn=?",Long.class,company,sn);}
    private long planned(Map<String,Object> n){return id(n.get("numberExpected"));}
    private Map<String,Object> ticket(String company,long receipt){List<Map<String,Object>> rows=db.jdbc.queryForList("SELECT t.* FROM wms_tickets t JOIN no_tickets n ON n.no_sn=t.relation_sn AND UPPER(n.company_code)=UPPER(t.company_code) WHERE UPPER(t.company_code)=? AND n.id=? AND t.ticket_type=1 ORDER BY t.id",company,receipt);require(rows.size()<=1,"到货单存在多个入库执行单，请核对");return rows.isEmpty()?null:rows.get(0);}
    public Map<String,Object> request(String company,String kind,long key,Map<String,Object> input,String actor){
        require(Arrays.asList("receipt","purchase").contains(kind),"请从到货单或采购单发起截单");String reason=required(input,"reason",500);require(input.containsKey("cutoff_version"),"请刷新单据后操作");
        return db.tx().execute(tx->{Map<String,Object> target=purchase.lockDocument(company,kind,key);require(id(target.get("cutoffVersion"))==id(input.get("cutoff_version")),"截单状态已变化，请刷新后操作");
            Map<String,Object> po="purchase".equals(kind)?target:db.jdbc.queryForList("SELECT id FROM po_info WHERE UPPER(company_code)=? AND po_sn=?",company,target.get("poSn")).stream().findFirst().orElseThrow(()->new IllegalArgumentException("采购单不存在"));long poId=id(po.get("id"));po=purchase.lockDocument(company,"purchase",poId);
            require(Arrays.asList(2L,3L).contains(id(po.get("poState"))),"采购单已结束，不能发起新的截单");require(!"PROCESSING".equals(po.get("cutoffState")),"采购单正在终止剩余采购，请处理原申请");
            String mode="receipt".equals(kind)?"WITHDRAW":required(input,"mode",16);require(Arrays.asList("WITHDRAW","TERMINATE").contains(mode),"请选择截单目的");String scope="receipt".equals(kind)?"RECEIPT":"TERMINATE".equals(mode)?"PURCHASE":"RECEIPTS";
            List<Long> ids=new ArrayList<>();if("receipt".equals(kind))ids.add(key);else if("PURCHASE".equals(scope)){require(db.jdbc.queryForObject("SELECT COUNT(*) FROM no_tickets WHERE UPPER(company_code)=? AND po_sn=? AND cutoff_state<>'' AND cutoff_state<>'COMPLETED'",Long.class,company,po.get("poSn"))==0,"有到货单截单尚未结束，请先核对原申请");ids.addAll(db.jdbc.queryForList("SELECT id FROM no_tickets WHERE UPPER(company_code)=? AND po_sn=? AND no_state IN (1,2,3) ORDER BY id",Long.class,company,po.get("poSn")));}
            else{require(input.get("receipt_ids") instanceof List,"请选择到货单");for(Object v:(List<?>)input.get("receipt_ids"))ids.add(id(v));require(!ids.isEmpty()&&ids.size()<=100&&new HashSet<>(ids).size()==ids.size(),"请选择1至100张不同到货单");Collections.sort(ids);}
            require(ids.size()<=100,"本次最多处理100张到货单，请分批撤回");List<Map<String,Object>> receipts=new ArrayList<>();for(long receipt:ids){Map<String,Object> n=purchase.lockDocument(company,"receipt",receipt);require(text(n.get("poSn")).equals(text(po.get("poSn"))),"到货单不属于当前采购单");require(!active(n),"到货单已有截单申请，请处理原申请");require(Arrays.asList(1L,2L,3L).contains(id(n.get("noState"))),"到货单已结束，不能重复截单");Map<String,Object> t=ticket(company,receipt);if(t!=null)require(received(company,text(t.get("sn")))<planned(n)||"PURCHASE".equals(scope),"到货单已全部实收，请核对记账或走采购退货");receipts.add(n);}
            long op=db.insert("purchase_cutoff",map("company_code",company,"purchase_id",poId,"scope",scope,"receipt_id","receipt".equals(kind)?key:null,"reason",reason,"operator_name",actor));
            for(Map<String,Object> n:receipts){Map<String,Object> t=ticket(company,id(n.get("id")));db.insert("purchase_cutoff_item",map("company_code",company,"cutoff_id",op,"receipt_id",n.get("id"),"receipt_sn",n.get("noSn"),"ticket_id",t==null?null:t.get("id"),"ticket_sn",t==null?"":t.get("sn")));db.jdbc.update("UPDATE no_tickets SET cutoff_state='PROCESSING',cutoff_id=?,cutoff_version=cutoff_version+1 WHERE id=? AND UPPER(company_code)=?",op,n.get("id"),company);if(t!=null)db.jdbc.update("UPDATE wms_tickets SET cutoff_state='PROCESSING' WHERE id=? AND UPPER(company_code)=?",t.get("id"),company);purchase.recordWmsEvent(company,text(n.get("noSn")),"申请到货单截单",actor+"："+reason);}
            db.jdbc.update("UPDATE po_info SET cutoff_id=?,cutoff_version=cutoff_version+1,cutoff_state=CASE WHEN ? THEN 'PROCESSING' ELSE cutoff_state END WHERE id=? AND UPPER(company_code)=?",op,"PURCHASE".equals(scope),poId,company);
            if("PURCHASE".equals(scope))purchase.recordWmsEvent(company,text(po.get("poSn")),"申请终止剩余采购",actor+"："+reason);return map("id",op,"state","PROCESSING");
        });
    }
    public Map<String,Object> report(String company,String kind,long key){
        require(Arrays.asList("receipt","purchase").contains(kind),"单据类型无效");String table=kind.equals("receipt")?"no_tickets":"po_info";Map<String,Object> target=db.one("SELECT * FROM "+table+" WHERE UPPER(company_code)=? AND id=?",company,key);
        List<Map<String,Object>> ops=db.jdbc.queryForList("SELECT o.* FROM purchase_cutoff o WHERE o.company_code=? AND "+(kind.equals("purchase")?"o.purchase_id=?":"EXISTS(SELECT 1 FROM purchase_cutoff_item i WHERE i.company_code=o.company_code AND i.cutoff_id=o.id AND i.receipt_id=?)")+" ORDER BY o.id DESC LIMIT 20",company,key);
        for(Map<String,Object> op:ops)op.put("items",db.jdbc.queryForList("SELECT * FROM purchase_cutoff_item WHERE company_code=? AND cutoff_id=? ORDER BY id",company,op.get("id")));
        List<Map<String,Object>> reviews=db.jdbc.queryForList("SELECT r.id,r.ticket_id,r.ticket_sn,r.message_id,r.state,r.conflict_message,r.reason,r.operator_name,r.control_version,r.create_time,r.decided_at FROM wms_inbound_receipt_review r JOIN wms_tickets t ON t.id=r.ticket_id AND UPPER(t.company_code)=r.company_code JOIN no_tickets n ON n.no_sn=t.relation_sn AND UPPER(n.company_code)=r.company_code WHERE r.company_code=? AND "+(kind.equals("receipt")?"n.id=?":"n.po_sn=?")+" ORDER BY r.id DESC LIMIT 50",company,kind.equals("receipt")?key:target.get("po_sn"));
        return map("operations",ops,"reviews",reviews,"cutoff_version",target.get("cutoff_version"));
    }
    public void process(String company,long op){
        Map<String,Object> request=db.one("SELECT * FROM purchase_cutoff WHERE company_code=? AND id=?",company,op);if("COMPLETED".equals(request.get("state")))return;
        List<Map<String,Object>> items=db.jdbc.queryForList("SELECT * FROM purchase_cutoff_item WHERE company_code=? AND cutoff_id=? AND state<>'COMPLETED' ORDER BY id LIMIT 3",company,op);
        for(Map<String,Object> item:items)try{processItem(company,request,item);}catch(Review e){pending(company,item,"WAIT_REVIEW",e.getMessage());}catch(Exception e){pending(company,item,"PENDING",e instanceof IllegalArgumentException?text(e.getMessage()):"处理结果待确认，请核对原申请");}
        finish(company,request);
    }
    private void pending(String company,Map<String,Object> item,String state,String error){db.jdbc.update("UPDATE no_tickets SET cutoff_state=? WHERE UPPER(company_code)=? AND id=? AND cutoff_id=? AND cutoff_state<>'COMPLETED'","WAIT_REVIEW".equals(state)?"WAIT_REVIEW":"PROCESSING",company,item.get("receipt_id"),item.get("cutoff_id"));db.jdbc.update("UPDATE purchase_cutoff_item SET state=?,last_error=? WHERE company_code=? AND id=? AND state<>'COMPLETED'",state,error.substring(0,Math.min(error.length(),1000)),company,item.get("id"));}
    private Map<String,Object> snapshot(String company,Map<String,Object> item){return db.tx().execute(tx->{Map<String,Object> n=purchase.lockDocument(company,"receipt",id(item.get("receipt_id")));Map<String,Object> current=db.one("SELECT * FROM purchase_cutoff_item WHERE company_code=? AND id=? FOR UPDATE",company,item.get("id"));Map<String,Object> t=ticket(company,id(n.get("id")));if(t!=null){purchase.lockDocument(company,"ticket",id(t.get("id")));t=db.one("SELECT * FROM wms_tickets WHERE UPPER(company_code)=? AND id=?",company,t.get("id"));}return map("receipt",n,"item",current,"ticket",t);});}
    @SuppressWarnings("unchecked") private void processItem(String company,Map<String,Object> op,Map<String,Object> item){
        Map<String,Object> snapshot=snapshot(company,item),n=(Map<String,Object>)snapshot.get("receipt"),t=(Map<String,Object>)snapshot.get("ticket"),current=(Map<String,Object>)snapshot.get("item");if("COMPLETED".equals(current.get("state")))return;
        long actual=t==null?0:received(company,text(t.get("sn")));if(t!=null&&reviewCount(company,id(t.get("id")))>0)throw new Review("仓库收货回传待人工核对，暂不释放到货安排额度");
        boolean full=actual>=planned(n);String proof=text(current.get("warehouse_state"));
        if(!Arrays.asList("CONFIRMED","MANUAL_CONFIRMED","NOT_REQUIRED","FULL_RECEIVED","FINAL_RECEIPT").contains(proof)){
            if(t==null||id(t.get("actual_warehouse"))==2){proof="NOT_REQUIRED";}
            else if(full){proof="FULL_RECEIVED";}
            else{
                Map<String,Object> task=inbound.task(company,id(t.get("id")));if(task==null)throw new Review("真实入库任务缺失，请核对；不能按未下发处理");String state=text(task.get("dispatch_state")),cancel=text(task.get("cancel_state"));
                if("COMPLETE".equals(task.get("receipt_state"))&&finalReceipt(company,id(task.get("id"))))proof="FINAL_RECEIPT";else if("CONFIRMED".equals(cancel)||"CANCELED".equals(state))proof="CONFIRMED";
                else if("REJECTED".equals(cancel))throw new Review("仓库拒绝取消，原到货安排保留；核对后可重试原申请");
                else if(Arrays.asList("UNKNOWN","CANCEL_PENDING").contains(state)||Arrays.asList("PENDING","UNKNOWN").contains(cancel)||"FAILED".equals(state)||("PENDING".equals(state)&&id(task.get("attempts"))>0)){
                    inbound.query(company,id(t.get("id")));task=inbound.task(company,id(t.get("id")));if("CONFIRMED".equals(task.get("cancel_state"))||"CANCELED".equals(task.get("dispatch_state")))proof="CONFIRMED";else{pending(company,item,"PENDING","仓库结果待确认，继续核对原任务，不重复下发或释放额度");return;}
                }else if("SENDING".equals(state)){pending(company,item,"PENDING","原入库单正在下发，等待受理结果后截单");return;}
                else{
                    if(actual>0&&db.jdbc.queryForObject("SELECT partial_inbound_cancel FROM wms_connection WHERE company_code=? AND id=?",Integer.class,company,task.get("connection_id"))!=1)throw new Review("仓库未确认支持部分收货后关闭余量，请联系仓库截停并登记核对结果");
                    inbound.cancel(company,id(t.get("id")),text(op.get("reason")),text(op.get("operator_name")));task=inbound.task(company,id(t.get("id")));if("CONFIRMED".equals(task.get("cancel_state"))||"CANCELED".equals(task.get("dispatch_state")))proof="CONFIRMED";else{if("REJECTED".equals(task.get("cancel_state")))throw new Review("仓库拒绝取消，原到货安排保留");pending(company,item,"PENDING","取消申请已提交，等待仓库明确确认");return;}
                }
            }
            final String confirmed=proof;final long qty=actual;db.tx().execute(tx->{purchase.lockDocument(company,"receipt",id(item.get("receipt_id")));db.jdbc.update("UPDATE purchase_cutoff_item SET warehouse_state=?,confirmed_received=?,state='POSTING_PENDING',last_error='' WHERE company_code=? AND id=? AND state<>'COMPLETED'",confirmed,qty,company,item.get("id"));return null;});
        }
        if(t!=null){if(id(t.get("actual_warehouse"))==1){long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_receipt_line WHERE company_code=? AND task_id=(SELECT id FROM wms_inbound_task WHERE company_code=? AND ticket_id=?) AND posted<>1",Long.class,company,company,t.get("id"));if(count>0&&!inbound.post(company,id(t.get("id")))){pending(company,item,"POSTING_PENDING","仓库已截停，已实收明细尚未全部入账；到货额度继续保留");return;}}
            else if(actual>0&&id(t.get("inventory_status"))!=2&&!purchase.postInventory(company,id(t.get("id")),text(op.get("operator_name")))){pending(company,item,"POSTING_PENDING","虚拟实收尚未完成入账，暂不释放额度");return;}}
        finalizeItem(company,op,item);
    }
    private boolean finalReceipt(String company,long task){return db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM wms_receipt_event WHERE company_code=? AND task_id=? AND final_receipt=1)",Integer.class,company,task)==1;}
    public long reviewCount(String company,long ticket){return db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_inbound_receipt_review WHERE company_code=? AND ticket_id=? AND state='WAIT_REVIEW'",Long.class,company,ticket);}
    private void finalizeItem(String company,Map<String,Object> op,Map<String,Object> item){db.tx().execute(tx->{Map<String,Object> n=purchase.lockDocument(company,"receipt",id(item.get("receipt_id")));Map<String,Object> cur=db.one("SELECT * FROM purchase_cutoff_item WHERE company_code=? AND id=? FOR UPDATE",company,item.get("id"));if("COMPLETED".equals(cur.get("state")))return null;Map<String,Object> t=ticket(company,id(n.get("id")));long actual=0,cancelled=planned(n);
        if(t!=null){purchase.lockDocument(company,"ticket",id(t.get("id")));require(reviewCount(company,id(t.get("id")))==0,"仍有收货回传待人工核对");actual=received(company,text(t.get("sn")));if(id(t.get("actual_warehouse"))==1){Map<String,Object> task=inbound.task(company,id(t.get("id")));require(task!=null,"仓库入库任务缺失");require(actual>=planned(n)||"CONFIRMED".equals(task.get("cancel_state"))||"CANCELED".equals(task.get("dispatch_state"))||"COMPLETE".equals(task.get("receipt_state"))&&finalReceipt(company,id(task.get("id"))),"仓库截停尚未确认");require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_receipt_line WHERE company_code=? AND task_id=? AND posted<>1",Long.class,company,task.get("id"))==0,"已实收记录仍有未完成记账");}else require(actual==0||id(db.one("SELECT inventory_status FROM wms_tickets WHERE id=? AND UPPER(company_code)=?",t.get("id"),company).get("inventory_status"))==2,"虚拟实收记账未确认");
            db.jdbc.update("UPDATE wms_tickets_goods SET cancelled_quantity=GREATEST(number_expected-number_actually,0) WHERE sn=? AND UPPER(company_code)=?",t.get("sn"),company);db.jdbc.update("UPDATE no_tickets_goods n JOIN wms_tickets_goods g ON g.sku_sn=n.sku_sn AND UPPER(g.company_code)=UPPER(n.company_code) SET n.cancelled_quantity=GREATEST(n.zp_number_expected+n.cp_number_expected-g.number_actually,0) WHERE UPPER(n.company_code)=? AND n.no_sn=? AND g.sn=?",company,n.get("noSn"),t.get("sn"));cancelled=Math.max(0,planned(n)-actual);db.jdbc.update("UPDATE wms_tickets SET cutoff_state='COMPLETED',cancelled_quantity=?,status_ticket=?,inventory_status=2 WHERE id=? AND UPPER(company_code)=?",cancelled,cancelled==0?2:actual>0?7:5,t.get("id"),company);
        }else db.jdbc.update("UPDATE no_tickets_goods SET cancelled_quantity=zp_number_expected+cp_number_expected WHERE UPPER(company_code)=? AND no_sn=?",company,n.get("noSn"));
        db.jdbc.update("UPDATE no_tickets SET cutoff_state='COMPLETED',cutoff_version=cutoff_version+1,cancelled_quantity=?,no_state=? WHERE id=? AND UPPER(company_code)=?",cancelled,cancelled==0?4:actual>0?5:6,n.get("id"),company);db.jdbc.update("UPDATE purchase_cutoff_item SET state='COMPLETED',cancelled_quantity=?,last_error='' WHERE company_code=? AND id=?",cancelled,company,item.get("id"));purchase.refreshPurchase(company,text(n.get("poSn")));purchase.recordWmsEvent(company,text(n.get("noSn")),"到货单截单完成","保留实收 "+actual+" 件，截停 "+cancelled+" 件；"+("PURCHASE".equals(op.get("scope"))?"等待整单采购终止核对":"原采购需求保留"));return null;});}
    private void finish(String company,Map<String,Object> op){db.tx().execute(tx->{Map<String,Object> po=purchase.lockDocument(company,"purchase",id(op.get("purchase_id")));List<Map<String,Object>> pending=db.jdbc.queryForList("SELECT state,last_error FROM purchase_cutoff_item WHERE company_code=? AND cutoff_id=? AND state<>'COMPLETED'",company,op.get("id"));boolean manual=pending.stream().anyMatch(r->"WAIT_REVIEW".equals(r.get("state")));if(!pending.isEmpty()){String state=manual?"WAIT_REVIEW":"PROCESSING";db.jdbc.update("UPDATE purchase_cutoff SET state=?,next_attempt=CASE WHEN ? THEN NULL ELSE DATE_ADD(NOW(),INTERVAL 30 SECOND) END,last_error=? WHERE company_code=? AND id=?",state,manual,pending.get(0).get("last_error"),company,op.get("id"));return null;}
        if("PURCHASE".equals(op.get("scope"))){if(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_inbound_receipt_review r JOIN wms_tickets t ON t.id=r.ticket_id AND UPPER(t.company_code)=r.company_code WHERE r.company_code=? AND t.original_sn=? AND r.state='WAIT_REVIEW'",Long.class,company,po.get("poSn"))>0){db.jdbc.update("UPDATE purchase_cutoff SET state='WAIT_REVIEW',next_attempt=NULL,last_error='仍有取消后收货回传待核对' WHERE company_code=? AND id=?",company,op.get("id"));return null;}require(db.jdbc.queryForObject("SELECT COUNT(*) FROM no_tickets WHERE UPPER(company_code)=? AND po_sn=? AND no_state NOT IN(-1,4,5,6)",Long.class,company,po.get("poSn"))==0,"仍有未结束到货单，不能关闭采购");db.jdbc.update("UPDATE po_info SET po_state=CASE WHEN number_actually>=number_expected THEN 4 ELSE 5 END,cutoff_state='COMPLETED',cutoff_version=cutoff_version+1,close_reason=? WHERE id=? AND UPPER(company_code)=?",op.get("reason"),po.get("id"),company);purchase.recordWmsEvent(company,text(po.get("poSn")),"终止剩余采购完成",text(op.get("reason")));}
        db.jdbc.update("UPDATE purchase_cutoff SET state='COMPLETED',last_error='',next_attempt=NULL,completed_at=NOW() WHERE company_code=? AND id=?",company,op.get("id"));return null;});}
    public long retry(String company,String kind,long key,long version,String actor){require(Arrays.asList("receipt","purchase").contains(kind),"单据类型无效");return db.tx().execute(tx->{Map<String,Object> target=purchase.lockDocument(company,kind,key);require(id(target.get("cutoffVersion"))==version,"请刷新后重试");long op=id(target.get("cutoffId"));require(!"COMPLETED".equals(db.one("SELECT state FROM purchase_cutoff WHERE company_code=? AND id=?",company,op).get("state")),"截单已完成");for(Map<String,Object> i:db.jdbc.queryForList("SELECT * FROM purchase_cutoff_item WHERE company_code=? AND cutoff_id=? AND state<>'COMPLETED' ORDER BY receipt_id",company,op)){purchase.lockDocument(company,"receipt",id(i.get("receipt_id")));db.jdbc.update("UPDATE no_tickets SET cutoff_state='PROCESSING' WHERE UPPER(company_code)=? AND id=? AND cutoff_state<>'COMPLETED'",company,i.get("receipt_id"));if(i.get("ticket_id")!=null)db.jdbc.update("UPDATE wms_inbound_task SET cancel_state=CASE WHEN cancel_state='REJECTED' THEN 'NONE' ELSE cancel_state END WHERE company_code=? AND ticket_id=?",company,i.get("ticket_id"));db.jdbc.update("UPDATE purchase_cutoff_item SET state='PENDING' WHERE company_code=? AND id=?",company,i.get("id"));}db.jdbc.update("UPDATE purchase_cutoff SET state='PROCESSING',next_attempt=NOW() WHERE company_code=? AND id=?",company,op);db.jdbc.update("UPDATE "+(kind.equals("receipt")?"no_tickets":"po_info")+" SET cutoff_version=cutoff_version+1 WHERE UPPER(company_code)=? AND id=?",company,key);return op;});}
    @SuppressWarnings("unchecked") public long confirmWarehouse(String company,long itemId,Map<String,Object> input,String actor){return db.tx().execute(tx->{Map<String,Object> item=db.one("SELECT * FROM purchase_cutoff_item WHERE company_code=? AND id=?",company,itemId);Map<String,Object> n=purchase.lockDocument(company,"receipt",id(item.get("receipt_id")));item=db.one("SELECT * FROM purchase_cutoff_item WHERE company_code=? AND id=? FOR UPDATE",company,itemId);require(!"COMPLETED".equals(item.get("state")),"本批截单已完成");require(item.get("ticket_id")!=null,"未生成入库单，无需人工仓库确认");Map<String,Object> t=purchase.lockDocument(company,"ticket",id(item.get("ticket_id")));Map<String,Object> task=inbound.task(company,id(t.get("id")));require(task!=null,"仓库任务不存在");Map<String,Object> locked=db.one("SELECT * FROM wms_inbound_task WHERE company_code=? AND id=? FOR UPDATE",company,task.get("id"));require(locked.get("lease_until")==null||db.jdbc.queryForObject("SELECT lease_until<NOW() FROM wms_inbound_task WHERE id=?",Integer.class,task.get("id"))==1,"仓库交互正在执行，请稍后核对");require(reviewCount(company,id(t.get("id")))==0,"请先处理待核对的收货回传");require(Boolean.TRUE.equals(input.get("confirmed_stopped")),"必须明确确认仓库已停止本批后续收货");String evidence=required(input,"evidence",500),external=required(input,"external_order",100);require(text(task.get("external_order")).isEmpty()||external.equals(task.get("external_order")),"仓库单号不一致");require(input.get("lines") instanceof List,"请核对每行正品、次品实收");List<Map<String,Object>> goods=db.jdbc.queryForList("SELECT id,number_zp,number_cp FROM wms_tickets_goods WHERE UPPER(company_code)=? AND sn=?",company,t.get("sn"));Map<Long,Map<String,Object>> seen=new HashMap<>();for(Object v:(List<?>)input.get("lines")){require(v instanceof Map,"实收参数无效");Map<String,Object> line=(Map<String,Object>)v;require(seen.put(id(line.get("id")),line)==null,"实收行重复");}require(seen.size()==goods.size(),"请核对全部商品行");for(Map<String,Object> g:goods){Map<String,Object> line=seen.get(id(g.get("id")));require(line!=null&&id(line.get("good"))==id(g.get("number_zp"))&&id(line.get("bad"))==id(g.get("number_cp")),"仓库最终实收与系统已接收数量不一致，请先补齐或核对回传，不能修改实收后强行截单");}db.jdbc.update("UPDATE wms_inbound_task SET dispatch_state='CANCELED',cancel_state='CONFIRMED',receipt_state='COMPLETE',external_order=?,last_error='' WHERE company_code=? AND id=?",external,company,task.get("id"));db.jdbc.update("UPDATE purchase_cutoff_item SET warehouse_state='MANUAL_CONFIRMED',confirmed_received=?,manual_evidence=?,state='POSTING_PENDING',last_error='' WHERE company_code=? AND id=?",received(company,text(t.get("sn"))),evidence,company,itemId);db.jdbc.update("UPDATE purchase_cutoff SET state='PROCESSING',next_attempt=NOW() WHERE company_code=? AND id=?",company,item.get("cutoff_id"));purchase.recordWmsEvent(company,text(n.get("noSn")),"人工登记仓库截停",actor+"："+evidence);return id(item.get("cutoff_id"));});}
    public void scan(String company){for(Long op:db.jdbc.queryForList("SELECT id FROM purchase_cutoff WHERE company_code=? AND next_attempt<=NOW() AND state<>'COMPLETED' ORDER BY next_attempt,id LIMIT 3",Long.class,company))try{process(company,op);}catch(RuntimeException e){db.jdbc.update("UPDATE purchase_cutoff SET last_error='本次核对未完成，请查看原申请',next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=? AND state<>'COMPLETED'",company,op);}}
}
